test('a hold is still active one millisecond before expiresAt', () => {
  const { clock, book } = setup();
  const hold = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 2 });
  assert.equal(hold.expiresAt, 10 * MIN);
  clock.set(10 * MIN - 1);
  assert.equal(book.available('cap'), 8);
});

test('standard and missing tiers hold for 10 minutes, vip for 30 minutes', () => {
  const { clock, book } = setup();
  const none = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 1 });
  const standard = book.reserve({ orderId: 'o2', sku: 'cap', quantity: 1, customerTier: 'standard' });
  const gold = book.reserve({ orderId: 'o3', sku: 'cap', quantity: 1, customerTier: 'gold' });
  const vip = book.reserve({ orderId: 'o4', sku: 'cap', quantity: 1, customerTier: 'vip' });
  assert.equal(none.expiresAt, 10 * MIN);
  assert.equal(standard.expiresAt, 10 * MIN);
  assert.equal(gold.expiresAt, 10 * MIN);
  assert.equal(vip.expiresAt, 30 * MIN);
  clock.set(10 * MIN);
  assert.equal(book.available('cap'), 9);
  clock.set(30 * MIN - 1);
  assert.equal(book.release(vip.id).status, 'released');
});

test('a vip hold expires exactly at 30 minutes', () => {
  const { clock, book } = setup();
  const vip = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 4, customerTier: 'vip' });
  clock.set(30 * MIN);
  assert.equal(book.available('cap'), 10);
  assert.throws(() => book.commit(vip.id), /reservation_expired/);
});

test('reserve is all-or-nothing: shortfall throws insufficient_stock and holds nothing', () => {
  const { stock, book } = setup();
  book.reserve({ orderId: 'o1', sku: 'cap', quantity: 7 });
  assert.throws(() => book.reserve({ orderId: 'o2', sku: 'cap', quantity: 4 }), /insufficient_stock/);
  assert.equal(book.available('cap'), 3);
  assert.equal(stock.level('cap', 'w1').held, 6);
  assert.equal(stock.level('cap', 'w2').held, 1);
  assert.throws(() => book.reserve({ orderId: 'o3', sku: 'nope', quantity: 1 }), /insufficient_stock/);
  const next = book.reserve({ orderId: 'o4', sku: 'cap', quantity: 3 });
  assert.equal(next.backorderQuantity, 0);
  assert.equal(next.id, 'res_2');
  assert.equal(book.available('cap'), 0);
});

test('cannot oversell: reserving everything then more fails', () => {
  const { book } = setup();
  const all = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 10 });
  assert.deepEqual(all.lines, [
    { warehouse: 'w1', quantity: 6 },
    { warehouse: 'w2', quantity: 4 },
  ]);
  assert.throws(() => book.reserve({ orderId: 'o2', sku: 'cap', quantity: 1 }), /insufficient_stock/);
  book.commit(all.id);
  assert.throws(() => book.reserve({ orderId: 'o3', sku: 'cap', quantity: 1 }), /insufficient_stock/);
});

test('allocation breaks priority ties by warehouse id and ignores held stock', () => {
  const levels = [
    { warehouse: 'wb', sku: 's', onHand: 5, held: 0, priority: 1 },
    { warehouse: 'wa', sku: 's', onHand: 5, held: 4, priority: 1 },
    { warehouse: 'w0', sku: 's', onHand: 2, held: 3, priority: 0 },
  ];
  assert.deepEqual(allocate(levels, 3), {
    lines: [
      { warehouse: 'wa', quantity: 1 },
      { warehouse: 'wb', quantity: 2 },
    ],
    backorderQuantity: 0,
  });
  assert.deepEqual(allocate(levels, 20), {
    lines: [
      { warehouse: 'wa', quantity: 1 },
      { warehouse: 'wb', quantity: 5 },
    ],
    backorderQuantity: 14,
  });
});

test('Stock copies levels and defaults held to 0', () => {
  const input = [{ warehouse: 'w1', sku: 'cap', onHand: 3, priority: 1 }];
  const stock = new Stock(input);
  stock.level('cap', 'w1').onHand = 0;
  assert.equal(input[0].onHand, 3);
  assert.equal(stock.level('cap', 'w1').held, 0);
});

test('releasing a committed reservation does not change held stock', () => {
  const { stock, book } = setup();
  const a = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 3 });
  book.reserve({ orderId: 'o2', sku: 'cap', quantity: 2 });
  book.commit(a.id);
  const released = book.release(a.id);
  assert.equal(released.status, 'committed');
  assert.equal(stock.level('cap', 'w1').held, 2);
  assert.equal(stock.level('cap', 'w1').onHand, 3);
  assert.equal(book.available('cap'), 5);
});

test('release of an expired hold changes nothing; unknown ids throw', () => {
  const { clock, book } = setup();
  const hold = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 3 });
  clock.set(10 * MIN);
  assert.equal(book.release(hold.id).status, 'expired');
  assert.equal(book.available('cap'), 10);
  assert.throws(() => book.release('res_99'), /reservation_not_found/);
  assert.throws(() => book.commit('res_99'), /reservation_not_found/);
});

test('commit expires due holds first', () => {
  const { clock, stock, book } = setup();
  const hold = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 3 });
  clock.set(10 * MIN);
  assert.throws(() => book.commit(hold.id), /reservation_expired/);
  assert.equal(stock.level('cap', 'w1').onHand, 6);
  assert.equal(stock.level('cap', 'w1').held, 0);
});

test('commit removes quantity from held and onHand; recommitting throws not_held', () => {
  const { stock, book } = setup();
  const hold = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 8 });
  assert.equal(book.commit(hold.id).status, 'committed');
  assert.deepEqual(
    stock.levels.map(({ onHand, held }) => ({ onHand, held })),
    [{ onHand: 0, held: 0 }, { onHand: 2, held: 0 }],
  );
  assert.throws(() => book.commit(hold.id), /reservation_not_held/);
  const other = book.reserve({ orderId: 'o2', sku: 'cap', quantity: 1 });
  book.release(other.id);
  assert.throws(() => book.commit(other.id), /reservation_not_held/);
});

test('request validation', () => {
  const { book } = setup();
  for (const request of [undefined, null, {}, { orderId: '', sku: 'cap', quantity: 1 }, { orderId: 'o1', sku: 5, quantity: 1 }])
    assert.throws(() => book.reserve(request), /invalid_request/);
  for (const quantity of [undefined, '2', NaN, Infinity, Number.MAX_SAFE_INTEGER + 1, true])
    assert.throws(() => book.reserve({ orderId: 'o1', sku: 'cap', quantity }), /invalid_quantity/);
  assert.equal(book.available('cap'), 10);
});

test('returned reservations are copies', () => {
  const { stock, book } = setup();
  const hold = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 2 });
  hold.status = 'committed';
  hold.lines[0].quantity = 999;
  const released = book.release(hold.id);
  assert.equal(released.status, 'released');
  assert.deepEqual(released.lines, [{ warehouse: 'w1', quantity: 2 }]);
  assert.equal(stock.level('cap', 'w1').held, 0);
});

test('audit records each state change and cannot be altered by callers', () => {
  let now = 0;
  const audit = new AuditLog();
  const stock = new Stock([{ warehouse: 'w1', sku: 'cap', onHand: 10, priority: 1 }]);
  const book = new ReservationBook(stock, () => now, audit);
  const a = book.reserve({ orderId: 'o1', sku: 'cap', quantity: 1 });
  const b = book.reserve({ orderId: 'o2', sku: 'cap', quantity: 1 });
  const c = book.reserve({ orderId: 'o3', sku: 'cap', quantity: 1 });
  now = 1;
  book.release(a.id);
  book.release(a.id);
  book.commit(b.id);
  now = 10 * MIN;
  book.available('cap');
  const expected = [
    { type: 'reserved', reservationId: 'res_1', at: 0 },
    { type: 'reserved', reservationId: 'res_2', at: 0 },
    { type: 'reserved', reservationId: 'res_3', at: 0 },
    { type: 'released', reservationId: 'res_1', at: 1 },
    { type: 'committed', reservationId: 'res_2', at: 1 },
    { type: 'expired', reservationId: c.id, at: 10 * MIN },
  ];
  const entries = audit.entries();
  assert.deepEqual(entries, expected);
  entries[0].type = 'tampered';
  entries.push({ type: 'fake' });
  entries.length = 0;
  assert.deepEqual(audit.entries(), expected);
});

test('AuditLog stores a copy of the recorded entry', () => {
  const audit = new AuditLog();
  const entry = { type: 'reserved', reservationId: 'res_1', at: 5 };
  audit.record(entry);
  entry.at = 99;
  audit.entries()[0].reservationId = 'res_x';
  assert.deepEqual(audit.entries(), [{ type: 'reserved', reservationId: 'res_1', at: 5 }]);
});
